/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: interFamily } = loadInter();



export type GrowthChartProps = Record<string, any>;

const GrowthChart: React.FC<GrowthChartProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 8,
  lineColor = "#ff2a2a",
  gridColor = "#1a1a1a",
  textColor = "#ffffff",
  title = "Quarterly Growth",
  subtitle = "Malloy Studio Performance",
  growthText = "+3800%",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timings
  const totalFrames = durationInSeconds * fps;
  const startDelay = Math.min(20, Math.floor(totalFrames * 0.1));
  const chartStartFrame = startDelay;
  const chartEndFrame = Math.floor(totalFrames * 0.85);

  const titleOpacity = interpolate(frame, [0, startDelay || 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  const chartProgress = interpolate(
    frame,
    [chartStartFrame, chartEndFrame],
    [0, 1],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Dynamic count-up for badge percentage based on chart progress
  const targetPercentage = parseInt(growthText.replace(/[^0-9]/g, ""), 10) || 3800;
  const currentPercentage = Math.floor(
    interpolate(chartProgress, [0, 1], [0, targetPercentage], {
      easing: Easing.out(Easing.ease),
    })
  );
  const hasPlus = growthText.startsWith("+");
  const displayGrowthText = `${hasPlus ? "+" : ""}${currentPercentage}%`;

  const growthBadgeScale = spring({
    fps,
    frame: frame - Math.floor(chartEndFrame * 0.8),
    config: { damping: 12 },
  });

  // Curve reflects: flat early 90s, ticks up slightly, then accelerates and explodes upward
  const DATA_POINTS = [
    { x: 0.1, y: 0.82 }, // Early 90s (flat)
    { x: 0.2, y: 0.82 }, // Flat
    { x: 0.3, y: 0.8 }, // Slight tick up
    { x: 0.4, y: 0.77 }, // Slight tick up
    { x: 0.5, y: 0.7 }, // Ticks up slightly
    { x: 0.6, y: 0.6 }, // Accelerates upward
    { x: 0.7, y: 0.45 }, // Sharp rise
    { x: 0.8, y: 0.28 }, // Exploding upward
    { x: 0.9, y: 0.15 }, // Reached peak
  ];

  const absPoints = DATA_POINTS.map((p) => ({
    x: p.x * width,
    y: p.y * height,
  }));

  const minX = absPoints[0].x;
  const maxX = absPoints[absPoints.length - 1].x;

  const currentX = interpolate(chartProgress, [0, 1], [minX, maxX]);

  // Helper to find exact Y position on the piecewise linear graph for a given X
  function getYAtX(x: number, pts: { x: number; y: number }[]) {
    if (x <= pts[0].x) return pts[0].y;
    if (x >= pts[pts.length - 1].x) return pts[pts.length - 1].y;
    for (let i = 0; i < pts.length - 1; i++) {
      if (x >= pts[i].x && x <= pts[i + 1].x) {
        const p1 = pts[i];
        const p2 = pts[i + 1];
        if (p2.x === p1.x) return p1.y;
        const t = (x - p1.x) / (p2.x - p1.x);
        return p1.y + t * (p2.y - p1.y);
      }
    }
    return pts[pts.length - 1].y;
  }

  const currentY = getYAtX(currentX, absPoints);

  const linePath = absPoints
    .map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`)
    .join(" ");

  const areaPath = `${linePath} L ${maxX} ${height * 0.9} L ${minX} ${height * 0.9} Z`;

  const yLabels = [
    { y: 0.15, label: "$79" },
    { y: 0.38, label: "$53" },
    { y: 0.6, label: "$28" },
    { y: 0.82, label: "$2" },
  ];

  const leadingDotScale = interpolate(chartProgress, [0, 0.05], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const lineOpacity = interpolate(chartProgress, [0, 0.02], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Peak glow pulse
  const pulseProgress = interpolate(
    frame,
    [chartEndFrame - 10, chartEndFrame, chartEndFrame + 15, totalFrames],
    [1, 2.5, 1.2, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Retail Investors (Stick Figures) Timeline Configuration
  const figuresCount = 20;
  const FIGURES = Array.from({ length: figuresCount }).map((_, i) => {
    const x = 0.13 + (i / (figuresCount - 1)) * 0.74;
    const spawnFrame = Math.floor(
      interpolate(x, [0.1, 0.9], [chartStartFrame, chartEndFrame])
    );
    return {
      id: i,
      x,
      spawnFrame,
      coinSpawnFrame: spawnFrame + 4,
    };
  });

  // End screen dramatic text fade in
  const textFadeInFrame = Math.floor(totalFrames * 0.68);
  const overlayTextOpacity = interpolate(
    frame,
    [textFadeInFrame, textFadeInFrame + 25],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Background Grid & Labels */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        {yLabels.map((lbl, i) => {
          const yPos = lbl.y * height;
          return (
            <line
              key={`grid-${i}`}
              x1={width * 0.1}
              y1={yPos}
              x2={width * 0.9}
              y2={yPos}
              stroke={gridColor}
              strokeWidth={2}
              opacity={0.6}
            />
          );
        })}
      </svg>

      <div style={{ position: "absolute", top: 0, left: 0, width, height }}>
        {yLabels.map((lbl, i) => {
          const yPos = lbl.y * height;
          return (
            <div
              key={`label-${i}`}
              style={{
                position: "absolute",
                top: yPos - 15,
                right: width - width * 0.08,
                color: textColor,
                fontSize: 22,
                opacity: titleOpacity * 0.4,
                textAlign: "right",
              }}
            >
              {lbl.label}
            </div>
          );
        })}
      </div>

      {/* Early 90s label placement */}
      <div
        style={{
          position: "absolute",
          left: width * 0.1,
          top: height * 0.86,
          color: textColor,
          fontSize: 22,
          fontWeight: 500,
          opacity: titleOpacity * 0.6,
        }}
      >
        Early 90s
      </div>

      {/* Main Chart SVG */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, opacity: lineOpacity }}
      >
        <defs>
          <clipPath id="graph-clip">
            <rect x={0} y={0} width={currentX} height={height} />
          </clipPath>
          <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={lineColor} stopOpacity={0.4} />
            <stop offset="100%" stopColor={lineColor} stopOpacity={0.0} />
          </linearGradient>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation={10 * pulseProgress} result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Gradient Area Fill */}
        <path
          d={areaPath}
          fill="url(#area-gradient)"
          clipPath="url(#graph-clip)"
          style={{ transition: "none" }}
        />

        {/* Main Graph Line */}
        <path
          d={linePath}
          fill="none"
          stroke={lineColor}
          strokeWidth={6}
          strokeLinecap="round"
          strokeLinejoin="round"
          clipPath="url(#graph-clip)"
          filter="url(#glow)"
          style={{ transition: "none" }}
        />

        {/* Dynamic stick figure generation & interactive coin drop */}
        {FIGURES.map((fig) => {
          if (frame < fig.spawnFrame) return null;

          const appearanceProgress = spring({
            fps,
            frame: frame - fig.spawnFrame,
            config: { damping: 14, stiffness: 100 },
          });

          const coinProgress = interpolate(
            frame - fig.coinSpawnFrame,
            [0, 16],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const figX = fig.x * width;
          const figY = height * 0.88; // Ground placement
          const chartY = getYAtX(figX, absPoints);
          const handY = figY - 26;

          // Coins drop from investor hands down onto the active line
          const coinY = interpolate(coinProgress, [0, 1], [handY, chartY]);
          const coinOpacity = interpolate(
            coinProgress,
            [0, 0.1, 0.8, 1],
            [0, 1, 1, 0]
          );

          return (
            <g
              key={fig.id}
              style={{
                opacity: appearanceProgress,
                transform: `scale(${appearanceProgress})`,
                transformOrigin: `${figX}px ${figY}px`,
              }}
            >
              {/* Head */}
              <circle cx={figX} cy={figY - 32} r={6} fill={textColor} />
              {/* Spine */}
              <line
                x1={figX}
                y1={figY - 26}
                x2={figX}
                y2={figY - 12}
                stroke={textColor}
                strokeWidth={2.5}
              />
              {/* Arms tossing coin */}
              <line
                x1={figX}
                y1={figY - 22}
                x2={figX - 8}
                y2={figY - 26}
                stroke={textColor}
                strokeWidth={2.5}
              />
              <line
                x1={figX}
                y1={figY - 22}
                x2={figX + 8}
                y2={figY - 26}
                stroke={textColor}
                strokeWidth={2.5}
              />
              {/* Legs */}
              <line
                x1={figX}
                y1={figY - 12}
                x2={figX - 6}
                y2={figY}
                stroke={textColor}
                strokeWidth={2.5}
              />
              <line
                x1={figX}
                y1={figY - 12}
                x2={figX + 6}
                y2={figY}
                stroke={textColor}
                strokeWidth={2.5}
              />

              {/* Falling Coin */}
              {frame >= fig.coinSpawnFrame && coinProgress < 1 && (
                <circle
                  cx={figX + 8}
                  cy={coinY}
                  r={4}
                  fill="#ffd700"
                  opacity={coinOpacity}
                />
              )}
            </g>
          );
        })}

        {/* Dynamic Background Data Point Dots */}
        {absPoints.map((p, i) => {
          const dotScale = interpolate(
            currentX,
            [p.x, p.x + (maxX - minX) * 0.04],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <circle
              key={`dot-${i}`}
              cx={p.x}
              cy={p.y}
              r={6}
              fill={backgroundColor}
              stroke={lineColor}
              strokeWidth={3}
              style={{
                transform: `scale(${dotScale})`,
                transformOrigin: `${p.x}px ${p.y}px`,
                transition: "none",
              }}
            />
          );
        })}

        {/* Leading Dot Follower */}
        {chartProgress > 0 && (
          <circle
            cx={currentX}
            cy={currentY}
            r={10}
            fill={backgroundColor}
            stroke={lineColor}
            strokeWidth={4}
            filter="url(#glow)"
            style={{
              transform: `scale(${leadingDotScale})`,
              transformOrigin: `${currentX}px ${currentY}px`,
              transition: "none",
            }}
          />
        )}
      </svg>

      {/* Dynamic Pulsating Halo at Peak */}
      {chartProgress >= 0.98 && (
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", top: 0, left: 0 }}
        >
          <circle
            cx={maxX}
            cy={absPoints[absPoints.length - 1].y}
            r={30 * pulseProgress}
            fill={lineColor}
            opacity={interpolate(pulseProgress, [1, 2.5], [0.35, 0])}
            style={{ pointerEvents: "none" }}
          />
        </svg>
      )}

      {/* Header UI */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: width * 0.1,
          right: width * 0.1,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column" }}>
          <h1
            style={{
              margin: 0,
              fontSize: 48,
              fontWeight: 600,
              color: textColor,
              opacity: titleOpacity,
            }}
          >
            {title}
          </h1>
          <h2
            style={{
              margin: 0,
              fontSize: 32,
              fontWeight: 400,
              color: textColor,
              opacity: titleOpacity * 0.5,
              marginTop: 8,
            }}
          >
            {subtitle}
          </h2>
        </div>

        {/* Growth Text Badge with dynamic counter mapping */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            padding: "16px 32px",
            borderRadius: "100px",
            position: "relative",
            overflow: "hidden",
            opacity: interpolate(growthBadgeScale, [0, 1], [0, 1]),
            transform: `scale(${growthBadgeScale})`,
            transformOrigin: "center right",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundColor: lineColor,
              opacity: 0.15,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              border: `2px solid ${lineColor}`,
              opacity: 0.3,
              borderRadius: "100px",
            }}
          />
          <span
            style={{
              position: "relative",
              fontSize: 48,
              fontWeight: 700,
              color: lineColor,
            }}
          >
            {displayGrowthText}
          </span>
        </div>
      </div>

      {/* Cinematic Headline Text Overlay */}
      {frame >= textFadeInFrame && (
        <div
          style={{
            position: "absolute",
            bottom: height * 0.22,
            left: width * 0.12,
            color: lineColor,
            fontSize: 42,
            fontWeight: 800,
            opacity: overlayTextOpacity,
            textShadow: `0 0 20px rgba(255, 42, 42, 0.5)`,
            maxWidth: "60%",
            lineHeight: 1.4,
          }}
        >
          Retail saw the internet.<br />
          <span style={{ color: textColor, fontWeight: 500 }}>
            And they all piled in.
          </span>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default GrowthChart;